from collections import deque

def logistic_map(width, height, x_coords, y_coords):
    if not x_coords:
        return [[None for _ in range(width)] for _ in range(height)]

    grid = [[float('inf')] * width for _ in range(height)]
    queue = deque()

    for x, y in zip(x_coords, y_coords):
        grid[y][x] = 0
        queue.append((x, y))

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < width and 0 <= ny < height and grid[ny][nx] > grid[y][x] + 1:
                grid[ny][nx] = grid[y][x] + 1
                queue.append((nx, ny))

    return grid
